(121, 1, '2024-12-17 20:35:02', '2024-12-17 20:35:02', '<!-- wp:carbon-fields/main-screen {\"data\":{\"dolphincargo_home_page_main_screen_title\":\"DOLPHIN Cargo\",\"dolphincargo_home_page_main-screen_who_are_we\":\"Доставка вантажів з Китаю та Європи\",\"dolphincargo_home_page_main-screen_image\":\"http://dolphincargo.loc/wp-content/uploads/2024/12/home-main-bg_optimized.png\",\"dolphincargo_home_page_our_numbers_list\":[{\"_id\":\"cf-RBJ8fIpBSfrf0Rl5B34yv\",\"_type\":\"_\",\"number\":\"19 \",\"number_more\":\"років\",\"description\":\"досвіду та експертності\"},{\"_id\":\"cf-dklJC0dDZfpQjuoRnD9V0\",\"_type\":\"_\",\"number\":\"3400\",\"number_more\":\"+\",\"description\":\"постійних клієнтів та партнерів\"},{\"_id\":\"cf-Ic_Ue6Q5FGM3X77Xvjea9\",\"_type\":\"_\",\"number\":\"16700\",\"number_more\":\"+\",\"description\":\"замовлень за 2024 рік\"}]}} /-->\n\n<!-- wp:carbon-fields/what-you-get {\"data\":{\"dolphincargo_home_page_what_you_get_list\":[{\"_id\":\"cf-HftprtpqIC1EyBFN56kM5\",\"_type\":\"_\",\"text\":\"Без посередників і переплат \"},{\"_id\":\"cf-55UYtgnC7JmgbMQuFf8lF\",\"_type\":\"_\",\"text\":\"Власні склади у ключових транспортних вузлах \"},{\"_id\":\"cf-VwpG4L2dQtXhzuPI6kwU6\",\"_type\":\"_\",\"text\":\"Страхування вантажу і гарантія безпеки  \"},{\"_id\":\"cf-FWKlvV7swh9RR3q0_AeEI\",\"_type\":\"_\",\"text\":\"Повна конфіденційність та вся відповідна документація   \"}],\"dolphincargo_home_page_what_you_get_list_image\":96}} /-->\n\n<!-- wp:carbon-fields/services-list {\"data\":{\"dolphincargo_our_services_title\":\"НАШІ ПОСЛУГи\",\"dolphincargo_our_services_list\":[{\"id\":26,\"type\":\"post\",\"subtype\":\"services\"},{\"id\":27,\"type\":\"post\",\"subtype\":\"services\"},{\"id\":28,\"type\":\"post\",\"subtype\":\"services\"},{\"id\":30,\"type\":\"post\",\"subtype\":\"services\"},{\"id\":29,\"type\":\"post\",\"subtype\":\"services\"},{\"id\":31,\"type\":\"post\",\"subtype\":\"services\"}],\"dolphincargo_our_services_run_text\":\"Services of the transportation \\u0026 logistics company DOLPHIN CARGO\"}} /-->\n\n<!-- wp:carbon-fields/airplane-call-to-action {\"data\":{\"dolphincargo_home_call_to_title\":\"НЕ МОЖЕТЕ ВИЗНАЧИТИСЬ З ОПТИМАЛЬНИМ ВАРІАНТОМ ПЕРЕВЕЗЕННЯ? \",\"dolphincargo_home_call_to_text\":\"\\u003cp\\u003eНаші менеджери підберуть найкращі індивідуальні рішення саме під запити вашого бізнесу\\u003c/p\\u003e\",\"dolphincargo_home_call_to_image\":98}} /-->\n\n<!-- wp:carbon-fields/about-us {\"data\":{\"dolphincargo_block_about_us_title\":\"ПЕРЕВІРЕНІ ЧАСОМ —  НАВЧЕНІ ДОСВІДОМ\",\"dolphincargo_block_about_us_text\":\"\\u003cp\\u003eDolphin Cargo — ми лідери серед українських логістичних компаній, що спеціалізуються на доставці вантажів з Китаю та Європи. З 2005 року ведемо бездоганну роботу, регулярно масштабуючи власні можливості та покращуючи сервіс для наших клієнтів.\\u003c/p\\u003e\\n\\u003cp\\u003e\\u003cbr /\\u003eМи беремо на себе вирішення всіх питань сторони логістики, організації та документообігу транспортування вантажів.\\u003c/p\\u003e\",\"dolphincargo_block_about_us_gallery\":[{\"_id\":\"cf-zFnEoB9KIeuYXu3esS1hJ\",\"_type\":\"_\",\"image\":112},{\"_id\":\"cf-r63llcq5oX7hB8PJ4HFn8\",\"_type\":\"_\",\"image\":111},{\"_id\":\"cf-eIhMDcuPRXMdVCaflThgx\",\"_type\":\"_\",\"image\":110}],\"dolphincargo_block_about_us_link\":[{\"id\":16,\"type\":\"post\",\"subtype\":\"page\"}]}} /-->\n\n<!-- wp:carbon-fields/advantages {\"data\":{\"dolphincargo_block_advantages_title\":\"ВАШ НАДІЙНИЙ ПАРТНЕР \\u003c/br\\u003e З ВАНТАЖОПЕРЕВЕЗЕНЬ\",\"dolphincargo_block_advantages_list\":[{\"_id\":\"cf-6CfizFOUrlPc6JAPMwq42\",\"_type\":\"_\",\"name\":\"Маємо власні склади у ключових транспортних вузлах: Китай, ЄС, Україна\",\"description\":\"\\u003cp\\u003eЦе дозволяє нам забезпечити надійну та оперативну доставку вантажів з Китаю та Європи, скоротити час транзиту, ваші витрати та забезпечити високий рівень сервісу.\\u003c/p\\u003e\"},{\"_id\":\"cf-FXJS40_w_OHdlLWhaoNGT\",\"_type\":\"_\",\"name\":\"Працюємо на результат та розуміємо потреби сучасних бізнесів\",\"description\":\"\\u003cp\\u003eЗабезпечуємо повний цикл послуг з вантажоперевезень, знаходимо гнучкі рішення для досягнення поставлених задач, використовуємо мультимодальні перевезення.\\u003c/p\\u003e\"},{\"_id\":\"cf-ZGRwsJDxBtK41zbjJGVqZ\",\"_type\":\"_\",\"name\":\"Гарантуємо прозорість та економне планування вашого бюджету\",\"description\":\"\\u003cp\\u003eНадаємо індивідуальний розрахунок вартості доставки та знаходимо найефективніші рішення перевезення ваших вантажів\\u003c/p\\u003e\"},{\"_id\":\"cf-8ev_lcBr0V8606xqPxas7\",\"_type\":\"_\",\"name\":\"За вами закріплюється персональний менеджер\",\"description\":\"\\u003cp\\u003eЗ моменту першої заявки і до отримання вами вантажу — наші менеджери надають професійний супровід та кваліфіковану підтримку на кожному з етапів.\\u003c/p\\u003e\"}],\"dolphincargo_block_advantages_top_image\":93,\"dolphincargo_block_advantages_top_bootom\":97,\"dolphincargo_block_advantages_bottom_image\":97}} /-->\n\n<!-- wp:carbon-fields/reviews-block {\"data\":{\"dolphincargo_block_reviews_title\":\"ВІДГУКИ НАШИХ КЛІЄНТІВ\"}} /-->', 'Головна', '', 'inherit', 'closed', 'closed', '', '10-revision-v1', '', '', '2024-12-17 20:35:02', '2024-12-17 20:35:02', '', 10, 'http://dolphincargo.loc/?p=121', 0, 'revision', '', 0),
(122, 1, '2024-12-17 20:36:43', '2024-12-17 20:36:43', '<!-- wp:carbon-fields/text-review {\"data\":{\"dolphincargo_reviews_card_text_content\":\"\\u003cp\\u003eЯ в бізнесі недавно, і логістика була для мене щось накшталт темного лісу.  \\u003c/p\\u003e\\n\\u003cp\\u003eЗ Dolphin Cargo з першого ж вантажу все пішло гладко. Пояснили, підказали, навіть допомогли з постачальником. Дуже вдячний за підтримку.\\u003c/p\\u003e\"}} /-->', 'Олександр Пархоменко, Харків.', '', 'publish', 'closed', 'closed', '', 'yevgeniya-n', '', '', '2025-08-14 15:22:28', '2025-08-14 15:22:28', '', 0, 'http://dolphincargo.loc/?post_type=reviews&#038;p=122', 0, 'reviews', '', 0),
(123, 1, '2024-12-17 21:02:52', '2024-12-17 21:02:52', '<!-- wp:carbon-fields/text-review {\"data\":{\"dolphincargo_reviews_card_text_content\":\"\\u003cp\\u003eТут реально працюють як для себе.  \\u003c/p\\u003e\\n\\u003cp\\u003e Я звикла до того, що щось десь піде не так. Але тут — приємний шок: документи в порядку, зв’язок постійний, на всі мої “а якщо...” є відповідь. Таке відчуття, що їх команда переживає за мій вантаж більше, ніж я сама.\\u003c/p\\u003e\"}} /-->', 'Олена Литвиненко, Львів', '', 'publish', 'closed', 'closed', '', 'oleksij-p', '', '', '2025-08-14 15:23:10', '2025-08-14 15:23:10', '', 0, 'http://dolphincargo.loc/?post_type=reviews&#038;p=123', 0, 'reviews', '', 0),
