(503, 1, '2025-01-19 16:17:34', '2025-01-19 16:17:34', '<!-- wp:carbon-fields/about-us-main-screen {\"data\":{\"dolphincargo_about_us_main_screen_title\":\"DOLPHIN Cargo\",\"dolphincargo_about_us_main_screen_who_are_we\":\"Доставка вантажів з Китаю та Європи\",\"dolphincargo_about_us_main-screen_image\":\"http://dolphincargo.loc/wp-content/uploads/2025/01/about-us-main-bg.png\",\"dolphincargo_about_us_main-screen_advantages_list\":[{\"_id\":\"cf-5TTb5u5olKpHTyzyVmtmW\",\"_type\":\"_\",\"name\":\"Доставка морем, авіа, мультимодальні перевезення\"},{\"_id\":\"cf-EN5r6igorDt4SPjFKgfeI\",\"_type\":\"_\",\"name\":\"Понад 19 років на ринку логістики\"},{\"_id\":\"cf-BHVUnALhzv1oNNNyQKM07\",\"_type\":\"_\",\"name\":\"Власні склади у стратегічно важливих для доставки країнах\"}]}} /-->\n\n<!-- wp:carbon-fields/about-company {\"data\":{\"dolphincargo_block_about_company_list\":[{\"_id\":\"cf-spd8Mx7SeX8nyNLCjVXfY\",\"_type\":\"_\",\"text\":\"Dolphin Cargo Service — ми провідна логістична компанія України, яка забезпечує ефективну доставку вантажів із Китаю та Європи.\"},{\"_id\":\"cf-fo_aFfngsBHchbr6UJ_gz\",\"_type\":\"_\",\"text\":\"Ми працюємо з 2005 року, постійно вдосконалюючи свої послуги та розширюючи географію співпраці.\"},{\"_id\":\"cf-2zugsvpTVK03IqlEefQnO\",\"_type\":\"_\",\"text\":\"Dolphin Cargo — ваш надійний партнер у світі міжнародної логістики.\"}],\"dolphincargo_block_about_company_marque\":\"Dolphin Cargo Service — ваш надійний партнер у світі міжнародної логістики\",\"dolphincargo_block_about_company_text\":\"\\u003cp\\u003eМи не просто організовуємо перевезення — ми створюємо для клієнтів комплексні логістичні рішення. Від пошуку товару і підготовки документів до повного контролю всіх етапів транспортування.\\u003c/p\\u003e\\n\\u003cp\\u003eНаш досвід, власні склади у стратегічних транспортних вузлах та безпосередня співпраця з перевізниками дозволяють надавати послуги без посередників і економлять ваші витрати.\\u003c/p\\u003e\\n\\u003cp\\u003eМи дбаємо про безпеку кожного вантажу, конфіденційність та своєчасну доставку.\\u003c/p\\u003e\",\"dolphincargo_block_about_company_image\":497}} /-->\n\n<!-- wp:carbon-fields/our-goals {\"data\":{\"dolphincargo_block_our_goals_list\":[{\"_id\":\"cf-4UGSi6i29E9KCmqfJHYpb\",\"_type\":\"_\",\"name\":\"Наша мета\",\"text\":\"\\u003cp\\u003e️Зробити міжнародну логістику максимально доступною та надійною для українських бізнесів. Що успішно ми і реалізуємо протягом 19 років.\\u003c/p\\u003e\\n\\u003cp\\u003eМи створюємо рішення, які спрощують міжнародну логістику, дозволяючи нашим клієнтам зосередитися на розвитку свого бізнесу.\\u003c/p\\u003e\"},{\"_id\":\"cf-mA79unMt6IdmOb19DX659\",\"_type\":\"_\",\"name\":\"МЕТА ДІЯЛЬНОСТІ\",\"text\":\"\\u003cp\\u003eНаша мета — забезпечити кожного партнера безпечними, вигідними та зручними перевезеннями, будуючи довгострокову співпрацю на основі довіри та професіоналізму.\\u003c/p\\u003e\"}],\"dolphincargo_block_our_goals_marque\":\"Ваш вантаж — наша відповідальність!\"}} /-->\n\n<!-- wp:carbon-fields/call-to-action {\"data\":{\"dolphincargo_call_to_action_title\":\"ХОЧЕШ БУТИ В КУРСІ ОСТАННІХ НОВИН?\",\"dolphincargo_call_to_action_text\":\"\\u003cp\\u003eПідпишись на нас в соцмережах\\u003c/p\\u003e\",\"dolphincargo_call_to_action_image\":502,\"dolphincargo_call_to_action_contact\":\"social\"}} /-->', 'Про нас', '', 'inherit', 'closed', 'closed', '', '16-revision-v1', '', '', '2025-01-19 16:17:34', '2025-01-19 16:17:34', '', 16, 'http://dolphincargo.loc/?p=503', 0, 'revision', '', 0),
