(751, 1, '2025-11-09 13:52:21', '2025-11-09 13:52:21', '<!-- wp:carbon-fields/container-main-screen {\"data\":{\"dolphincargo_container_main_screen_title\":\"ТИПИ ТА РОЗМІРИ МОРСЬКИХ \\u2028КОНТЕЙНЕРІВ\",\"dolphincargo_container_main_screen_who_are_we\":\"Підберемо оптимальний формат контейнеру під ваш вантаж, розрахуємо вартість доставки та забезпечимо повний логістичний супровід\",\"dolphincargo_container_main_screen_image\":\"http://dolphincargo.loc/wp-content/uploads/2025/02/fon-5_optimized-scaled.jpg\",\"dolphincargo_container_main_screen_image_larg\":\"http://dolphincargo.loc/wp-content/uploads/2025/02/fon-5_optimized-scaled.jpg\",\"dolphincargo_container_main_screen_image_mob\":\"http://dolphincargo.loc/wp-content/uploads/2025/02/fon-5_optimized-scaled.jpg\",\"dolphincargo_container_main_screen_advantages_list\":[{\"_id\":\"cf-EI3HxdhpjI7uTto2Xa_SM\",\"_type\":\"_\",\"name\":\"Найвигідніші варіанти доставки для вашого об’єму й типу вантажу\"},{\"_id\":\"cf-uBxA6kN34sEwijDCism0Y\",\"_type\":\"_\",\"name\":\"Без прихованих платежів, фіксований тариф \\u2028з реальними термінами\"},{\"_id\":\"cf-BuAbLfYB3ozwadfssfs3s\",\"_type\":\"_\",\"name\":\"Повний супровід контейнера — від завантаження до митного оформлення в Україні\"}]}} /-->\n\n<!-- wp:carbon-fields/more-choice-lessl-cost {\"data\":{\"dolphincargo_taobao_more_choice_title\":\"Ваш вантаж — під повним\\u003c/br\\u003e контролем від Китаю до України\",\"dolphincargo_taobao_more_choice_text\":\"\\u003cp\\u003eМорські контейнери — це універсальна й надійна тара, що використовується у міжнародній логістиці для транспортування вантажів різного типу.\\u003c/p\\u003e\",\"block_image\":734,\"dolphincargo_taobao_more_choice_list\":[{\"_id\":\"cf-7y6tRv8hdUzpQUP8Llym9\",\"_type\":\"_\",\"text\":\"Правильно обрані типи морських контейнерів забезпечують безпеку товару, оптимізують простір і допомагають зменшити вартість доставки.\"},{\"_id\":\"cf-7Zbw9W_stGPahJSQPBNxJ\",\"_type\":\"_\",\"text\":\"Dolphin Cargo спеціалізується на перевезеннях морських контейнерів з Китаю та Європи, підбираючи рішення під кожен маршрут, бюджет і об’єм.\"},{\"_id\":\"cf-GyTJPNzEPnv29Cu32v9Zn\",\"_type\":\"_\",\"text\":\"Наші клієнти отримують точні розрахунки, стабільні терміни та впевненість, що вантаж прибуде без пошкоджень і затримок.\"}]}} /-->\n\n<!-- wp:carbon-fields/container-call-to-action {\"data\":{\"dolphincargo_title\":\"НЕ ХОЧЕТЕ ВИТРАЧАТИ ЧАС \\u003cbr\\u003e\\u2028НА ДЕТАЛІ ТА РИЗИКУВАТИ?\",\"dolphincargo_text\":\"\\u003cp\\u003eМи беремо все на себе: підбір контейнера, документи, митницю, доставку.\\u003cbr /\\u003eПросто залиште заявку — і ми запустимо процес вже сьогодні.\\u003c/p\\u003e\",\"dolphincargo_image\":744}} /-->\n\n<!-- wp:carbon-fields/why-choose-us {\"data\":{\"dolphincargo_block_problem_title\":\"ЧОМУ ОБИРАЮТЬ НАС\",\"dolphincargo_block_problem_list\":[{\"_id\":\"cf-4JfcpqAmsSonh4PWOap2O\",\"_type\":\"_\",\"name\":\"Без посередників і переплат\",\"reason_list\":[{\"_id\":\"cf-0SQOhi2_yMcg5tqU9vrtP\",\"_type\":\"_\",\"text\":\"\\u003cp\\u003eМи працюємо напряму з китайськими портами та судноплавними лініями, тому вартість перевезення морських контейнерів безкомпромісно залишається прозорою і конкурентною.\\u2028Жодних додаткових націнок — лише реальні тарифи та фіксовані умови доставки.\\u003c/p\\u003e\"}]},{\"_id\":\"cf-831JqpA2N8VggAzL0fcmk\",\"_type\":\"_\",\"name\":\"Повний контроль на кожному етапі\",\"reason_list\":[{\"_id\":\"cf-opB9_tnUGnb4Cbrdi3rKt\",\"_type\":\"_\",\"text\":\"\\u003cp\\u003eМи відстежуємо контейнер із моменту завантаження в Китаї до прибуття в Україну.\\u2028Наші клієнти бачать статус вантажу в своєму особистому кабінеті.\\u2028Ваш морський контейнер з Китаю цілодобово під контролем нашої команди.\\u003c/p\\u003e\"}]},{\"_id\":\"cf-l1P4SLLgfPPYYEtpa1nbw\",\"_type\":\"_\",\"name\":\"Збірні контейнери — вигідне рішення для малих партій\",\"reason_list\":[{\"_id\":\"cf-FH6eMJWSdoCqd4rgmqDtB\",\"_type\":\"_\",\"text\":\"\\u003cp\\u003eНе обов’язково чекати на повне завантаження. Ми об’єднуємо ваш вантаж із іншими нашими клієнтами в збірні контейнери з Китаю, щоб ви платили лише за свій об’єм.\\u2028Ідеальне рішення для малого бізнесу та тестових партій.\\u003c/p\\u003e\"}]},{\"_id\":\"cf-fybsD0uESzl0ZLNOHfydk\",\"_type\":\"_\",\"name\":\"Сервіс під ключ — від розрахунку до митного оформлення\",\"reason_list\":[{\"_id\":\"cf-L8KwsgrnmWazD3xNrgRyP\",\"_type\":\"_\",\"text\":\"\\u003cp\\u003eМи беремо на себе всі клопоти: розрахунок вартості, вибір маршруту, підготовку документів і митне очищення в Україні.\\u2028Ви просто отримуєте вантаж — без черг, зайвої бюрократії й непередбачених витрат в підсумку.\\u003c/p\\u003e\"}]}]}} /-->\n\n<!-- wp:carbon-fields/reviews-block {\"data\":{\"dolphincargo_block_reviews_title\":\"ВІДГУКИ НАШИХ КЛІЄНТІВ\"}} /-->\n\n<!-- wp:carbon-fields/faq-block {\"data\":{\"dolphincargo_block_faq_title\":\"Питання та вiдповiдi\",\"dolphincargo_block_faq_list\":[{\"_id\":\"cf-nvd3SsKtefGPz1jJ0R0sY\",\"_type\":\"_\",\"question\":\"Скільки коштує перевезення морських контейнерів з Китаю?\",\"answer\":\"Вартість залежить від маршруту, типу контейнера та ваги вантажу.\\u2028Ми працюємо без посередників, тому пропонуємо чесні тарифи та детальний прорахунок — без “прихованих” комісій.\\u2028Щоб дізнатися точну суму, залиште заявку на сайті — наш менеджер розрахує доставку з урахуванням розмірів морського контейнера, типу вантажу й термінів.\"},{\"_id\":\"cf-qrXFbN8FxokqF396ThxoT\",\"_type\":\"_\",\"question\":\"Які бувають типи морських контейнерів і який обрати?\",\"answer\":\"\\u003cp\\u003eІснують різні типи контейнерів та їх класифікація: стандартні (Dry), підвищеної висоти (High Cube), рефрижераторні (Reefer), відкриті (Open Top, Flat Rack) та для рідин (Tank).\\u2028Якщо вага або обсяг невеликі, радимо скористатися збірним контейнером з Китаю Dolphin Cargo — це дає можливість об’єднати декілька відправлень і зменшити витрати.\\u003c/p\\u003e\"},{\"_id\":\"cf-OGKZNAaxVoCh0zzEx26Zg\",\"_type\":\"_\",\"question\":\"Які стандартні розміри морських контейнерів використовуються найчастіше?\",\"answer\":\"\\u003cp\\u003eУ міжнародній логістиці найпопулярніші — 20-футові та 40-футові моделі.\\u2028Розміри цих контейнерів стандартизовані: 20 ft має довжину 6,06 м і об’єм 33 м³, а 40 ft — довжину 12,19 м і об’єм 67–76 м³.\\u2028Ми допоможемо визначити, який формат вигідніший саме для вашого вантажу.\\u003c/p\\u003e\"},{\"_id\":\"cf-xQFIWPhQCQ0MQwkj2ecrw\",\"_type\":\"_\",\"question\":\"Що входить у послугу перевезення морського контейнера?\",\"answer\":\"\\u003cp\\u003eМи забезпечуємо повний цикл: підбір контейнера, бронювання місця на судні, оформлення документів у Китаї, доставку до України й митне очищення.\\u2028Ви отримуєте готове рішення “під ключ” — без зайвих етапів і посередників.\\u003c/p\\u003e\"},{\"_id\":\"cf-RrdJkNGgypSMLVZtbfpJo\",\"_type\":\"_\",\"question\":\"Скільки триває доставка морем з Китаю?\",\"answer\":\"\\u003cp\\u003eСередній термін — від 30 до 45 днів залежно від маршруту та порту відправлення.\\u2028Ми постійно моніторимо судноплавні лінії, тому підбираємо найшвидший варіант з урахуванням ваших побажань.\\u003c/p\\u003e\"},{\"_id\":\"cf-7NXbRp7NYfy9rRFbA_Nkn\",\"_type\":\"_\",\"question\":\"Як підготувати вантаж до перевезення морським контейнером?\",\"answer\":\"\\u003cp\\u003eЩоб доставка пройшла безпечно, важливо правильно підготувати товар до завантаження.\\u2028Усі предмети мають бути надійно упаковані — у палети, коробки або дерев’яні ящики, з відповідними позначеннями.\\u2028Ми враховуємо особливості вантажу: його пакування, необхідність вентиляції та формати розміщення, щоб уникнути пошкоджень під час перевезення морських контейнерів.\\u003c/p\\u003e\"},{\"_id\":\"cf-a2Z6tpHumYVRgapkpjaFO\",\"_type\":\"_\",\"question\":\"Чи можна об’єднати декілька відправлень у один контейнер?\",\"answer\":\"\\u003cp\\u003eТак, це один із найпопулярніших форматів доставки.\\u2028Ми пропонуємо збірні контейнери з Китаю, де декілька клієнтів ділять місце в одному контейнері та оплачують лише свій об’єм.\\u2028Це дозволяє суттєво зменшити витрати, не очікуючи повного завантаження.\\u2028Dolphin Cargo контролює процес консолідації вантажів і гарантує безпечне розміщення кожної партії.\\u003c/p\\u003e\"},{\"_id\":\"cf-xE63h6GjfAhxcaPJ1Kcvm\",\"_type\":\"_\",\"question\":\"Які документи потрібні для перевезення морського контейнера?\",\"answer\":\"\\u003cp\\u003eДля міжнародних перевезень зазвичай потрібні:\\u003c/p\\u003e\\u003cul role=\\u0022list\\u0022\\u003e\\u003cli\\u003eкомерційний інвойс;\\u003c/li\\u003e\\u003cli\\u003eпакувальний лист;\\u003c/li\\u003e\\u003cli\\u003eсертифікати походження або якості (за потреби);\\u003c/li\\u003e\\u003cli\\u003eконосамент (Bill of Lading).\\u2028\\u2028Ми беремо на себе підготовку всіх транспортних документів і перевірку правильності заповнення.\\u2028Клієнт отримує від нас повний пакет для митного оформлення в Україні — без ризику затримок чи штрафів.\\u003c/li\\u003e\\u003c/ul\\u003e\"}]}} /-->', 'ТИПИ ТА РОЗМІРИ МОРСЬКИХ  КОНТЕЙНЕРІВ', '', 'inherit', 'closed', 'closed', '', '724-revision-v1', '', '', '2025-11-09 13:52:21', '2025-11-09 13:52:21', '', 724, 'http://dolphincargo.loc/?p=751', 0, 'revision', '', 0),
(752, 1, '2025-11-09 13:55:01', '2025-11-09 13:55:01', '<!-- wp:carbon-fields/container-main-screen {\"data\":{\"dolphincargo_container_main_screen_title\":\"ТИПИ ТА РОЗМІРИ МОРСЬКИХ \\u2028КОНТЕЙНЕРІВ\",\"dolphincargo_container_main_screen_who_are_we\":\"Підберемо оптимальний формат контейнеру під ваш вантаж, розрахуємо вартість доставки та забезпечимо повний логістичний супровід\",\"dolphincargo_container_main_screen_image\":\"http://dolphincargo.loc/wp-content/uploads/2025/02/fon-5_optimized-scaled.jpg\",\"dolphincargo_container_main_screen_image_larg\":\"http://dolphincargo.loc/wp-content/uploads/2025/02/fon-5_optimized-scaled.jpg\",\"dolphincargo_container_main_screen_image_mob\":\"http://dolphincargo.loc/wp-content/uploads/2025/02/fon-5_optimized-scaled.jpg\",\"dolphincargo_container_main_screen_advantages_list\":[{\"_id\":\"cf-EI3HxdhpjI7uTto2Xa_SM\",\"_type\":\"_\",\"name\":\"Найвигідніші варіанти доставки для вашого об’єму й типу вантажу\"},{\"_id\":\"cf-uBxA6kN34sEwijDCism0Y\",\"_type\":\"_\",\"name\":\"Без прихованих платежів, фіксований тариф \\u2028з реальними термінами\"},{\"_id\":\"cf-BuAbLfYB3ozwadfssfs3s\",\"_type\":\"_\",\"name\":\"Повний супровід контейнера — від завантаження до митного оформлення в Україні\"}]}} /-->\n\n<!-- wp:carbon-fields/more-choice-lessl-cost {\"data\":{\"dolphincargo_taobao_more_choice_title\":\"Ваш вантаж — під повним\\u003c/br\\u003e контролем від Китаю до України\",\"dolphincargo_taobao_more_choice_text\":\"\\u003cp\\u003eМорські контейнери — це універсальна й надійна тара, що використовується у міжнародній логістиці для транспортування вантажів різного типу.\\u003c/p\\u003e\",\"block_image\":734,\"dolphincargo_taobao_more_choice_list\":[{\"_id\":\"cf-7y6tRv8hdUzpQUP8Llym9\",\"_type\":\"_\",\"text\":\"Правильно обрані типи морських контейнерів забезпечують безпеку товару, оптимізують простір і допомагають зменшити вартість доставки.\"},{\"_id\":\"cf-7Zbw9W_stGPahJSQPBNxJ\",\"_type\":\"_\",\"text\":\"Dolphin Cargo спеціалізується на перевезеннях морських контейнерів з Китаю та Європи, підбираючи рішення під кожен маршрут, бюджет і об’єм.\"},{\"_id\":\"cf-GyTJPNzEPnv29Cu32v9Zn\",\"_type\":\"_\",\"text\":\"Наші клієнти отримують точні розрахунки, стабільні терміни та впевненість, що вантаж прибуде без пошкоджень і затримок.\"}]}} /-->\n\n<!-- wp:carbon-fields/container-call-to-action {\"data\":{\"dolphincargo_title\":\"НЕ ХОЧЕТЕ ВИТРАЧАТИ ЧАС \\u003cbr\\u003eНА ДЕТАЛІ ТА РИЗИКУВАТИ?\",\"dolphincargo_text\":\"\\u003cp\\u003eМи беремо все на себе: підбір контейнера, документи, митницю, доставку.\\u003cbr /\\u003eПросто залиште заявку — і ми запустимо процес вже сьогодні.\\u003c/p\\u003e\",\"dolphincargo_image\":744}} /-->\n\n<!-- wp:carbon-fields/why-choose-us {\"data\":{\"dolphincargo_block_problem_title\":\"ЧОМУ ОБИРАЮТЬ НАС\",\"dolphincargo_block_problem_list\":[{\"_id\":\"cf-4JfcpqAmsSonh4PWOap2O\",\"_type\":\"_\",\"name\":\"Без посередників і переплат\",\"reason_list\":[{\"_id\":\"cf-0SQOhi2_yMcg5tqU9vrtP\",\"_type\":\"_\",\"text\":\"\\u003cp\\u003eМи працюємо напряму з китайськими портами та судноплавними лініями, тому вартість перевезення морських контейнерів безкомпромісно залишається прозорою і конкурентною.\\u2028Жодних додаткових націнок — лише реальні тарифи та фіксовані умови доставки.\\u003c/p\\u003e\"}]},{\"_id\":\"cf-831JqpA2N8VggAzL0fcmk\",\"_type\":\"_\",\"name\":\"Повний контроль на кожному етапі\",\"reason_list\":[{\"_id\":\"cf-opB9_tnUGnb4Cbrdi3rKt\",\"_type\":\"_\",\"text\":\"\\u003cp\\u003eМи відстежуємо контейнер із моменту завантаження в Китаї до прибуття в Україну.\\u2028Наші клієнти бачать статус вантажу в своєму особистому кабінеті.\\u2028Ваш морський контейнер з Китаю цілодобово під контролем нашої команди.\\u003c/p\\u003e\"}]},{\"_id\":\"cf-l1P4SLLgfPPYYEtpa1nbw\",\"_type\":\"_\",\"name\":\"Збірні контейнери — вигідне рішення для малих партій\",\"reason_list\":[{\"_id\":\"cf-FH6eMJWSdoCqd4rgmqDtB\",\"_type\":\"_\",\"text\":\"\\u003cp\\u003eНе обов’язково чекати на повне завантаження. Ми об’єднуємо ваш вантаж із іншими нашими клієнтами в збірні контейнери з Китаю, щоб ви платили лише за свій об’єм.\\u2028Ідеальне рішення для малого бізнесу та тестових партій.\\u003c/p\\u003e\"}]},{\"_id\":\"cf-fybsD0uESzl0ZLNOHfydk\",\"_type\":\"_\",\"name\":\"Сервіс під ключ — від розрахунку до митного оформлення\",\"reason_list\":[{\"_id\":\"cf-L8KwsgrnmWazD3xNrgRyP\",\"_type\":\"_\",\"text\":\"\\u003cp\\u003eМи беремо на себе всі клопоти: розрахунок вартості, вибір маршруту, підготовку документів і митне очищення в Україні.\\u2028Ви просто отримуєте вантаж — без черг, зайвої бюрократії й непередбачених витрат в підсумку.\\u003c/p\\u003e\"}]}]}} /-->\n\n<!-- wp:carbon-fields/reviews-block {\"data\":{\"dolphincargo_block_reviews_title\":\"ВІДГУКИ НАШИХ КЛІЄНТІВ\"}} /-->\n\n<!-- wp:carbon-fields/faq-block {\"data\":{\"dolphincargo_block_faq_title\":\"Питання та вiдповiдi\",\"dolphincargo_block_faq_list\":[{\"_id\":\"cf-nvd3SsKtefGPz1jJ0R0sY\",\"_type\":\"_\",\"question\":\"Скільки коштує перевезення морських контейнерів з Китаю?\",\"answer\":\"Вартість залежить від маршруту, типу контейнера та ваги вантажу.\\u2028Ми працюємо без посередників, тому пропонуємо чесні тарифи та детальний прорахунок — без “прихованих” комісій.\\u2028Щоб дізнатися точну суму, залиште заявку на сайті — наш менеджер розрахує доставку з урахуванням розмірів морського контейнера, типу вантажу й термінів.\"},{\"_id\":\"cf-qrXFbN8FxokqF396ThxoT\",\"_type\":\"_\",\"question\":\"Які бувають типи морських контейнерів і який обрати?\",\"answer\":\"\\u003cp\\u003eІснують різні типи контейнерів та їх класифікація: стандартні (Dry), підвищеної висоти (High Cube), рефрижераторні (Reefer), відкриті (Open Top, Flat Rack) та для рідин (Tank).\\u2028Якщо вага або обсяг невеликі, радимо скористатися збірним контейнером з Китаю Dolphin Cargo — це дає можливість об’єднати декілька відправлень і зменшити витрати.\\u003c/p\\u003e\"},{\"_id\":\"cf-OGKZNAaxVoCh0zzEx26Zg\",\"_type\":\"_\",\"question\":\"Які стандартні розміри морських контейнерів використовуються найчастіше?\",\"answer\":\"\\u003cp\\u003eУ міжнародній логістиці найпопулярніші — 20-футові та 40-футові моделі.\\u2028Розміри цих контейнерів стандартизовані: 20 ft має довжину 6,06 м і об’єм 33 м³, а 40 ft — довжину 12,19 м і об’єм 67–76 м³.\\u2028Ми допоможемо визначити, який формат вигідніший саме для вашого вантажу.\\u003c/p\\u003e\"},{\"_id\":\"cf-xQFIWPhQCQ0MQwkj2ecrw\",\"_type\":\"_\",\"question\":\"Що входить у послугу перевезення морського контейнера?\",\"answer\":\"\\u003cp\\u003eМи забезпечуємо повний цикл: підбір контейнера, бронювання місця на судні, оформлення документів у Китаї, доставку до України й митне очищення.\\u2028Ви отримуєте готове рішення “під ключ” — без зайвих етапів і посередників.\\u003c/p\\u003e\"},{\"_id\":\"cf-RrdJkNGgypSMLVZtbfpJo\",\"_type\":\"_\",\"question\":\"Скільки триває доставка морем з Китаю?\",\"answer\":\"\\u003cp\\u003eСередній термін — від 30 до 45 днів залежно від маршруту та порту відправлення.\\u2028Ми постійно моніторимо судноплавні лінії, тому підбираємо найшвидший варіант з урахуванням ваших побажань.\\u003c/p\\u003e\"},{\"_id\":\"cf-7NXbRp7NYfy9rRFbA_Nkn\",\"_type\":\"_\",\"question\":\"Як підготувати вантаж до перевезення морським контейнером?\",\"answer\":\"\\u003cp\\u003eЩоб доставка пройшла безпечно, важливо правильно підготувати товар до завантаження.\\u2028Усі предмети мають бути надійно упаковані — у палети, коробки або дерев’яні ящики, з відповідними позначеннями.\\u2028Ми враховуємо особливості вантажу: його пакування, необхідність вентиляції та формати розміщення, щоб уникнути пошкоджень під час перевезення морських контейнерів.\\u003c/p\\u003e\"},{\"_id\":\"cf-a2Z6tpHumYVRgapkpjaFO\",\"_type\":\"_\",\"question\":\"Чи можна об’єднати декілька відправлень у один контейнер?\",\"answer\":\"\\u003cp\\u003eТак, це один із найпопулярніших форматів доставки.\\u2028Ми пропонуємо збірні контейнери з Китаю, де декілька клієнтів ділять місце в одному контейнері та оплачують лише свій об’єм.\\u2028Це дозволяє суттєво зменшити витрати, не очікуючи повного завантаження.\\u2028Dolphin Cargo контролює процес консолідації вантажів і гарантує безпечне розміщення кожної партії.\\u003c/p\\u003e\"},{\"_id\":\"cf-xE63h6GjfAhxcaPJ1Kcvm\",\"_type\":\"_\",\"question\":\"Які документи потрібні для перевезення морського контейнера?\",\"answer\":\"\\u003cp\\u003eДля міжнародних перевезень зазвичай потрібні:\\u003c/p\\u003e\\u003cul role=\\u0022list\\u0022\\u003e\\u003cli\\u003eкомерційний інвойс;\\u003c/li\\u003e\\u003cli\\u003eпакувальний лист;\\u003c/li\\u003e\\u003cli\\u003eсертифікати походження або якості (за потреби);\\u003c/li\\u003e\\u003cli\\u003eконосамент (Bill of Lading).\\u2028\\u2028Ми беремо на себе підготовку всіх транспортних документів і перевірку правильності заповнення.\\u2028Клієнт отримує від нас повний пакет для митного оформлення в Україні — без ризику затримок чи штрафів.\\u003c/li\\u003e\\u003c/ul\\u003e\"}]}} /-->', 'ТИПИ ТА РОЗМІРИ МОРСЬКИХ  КОНТЕЙНЕРІВ', '', 'inherit', 'closed', 'closed', '', '724-revision-v1', '', '', '2025-11-09 13:55:01', '2025-11-09 13:55:01', '', 724, 'http://dolphincargo.loc/?p=752', 0, 'revision', '', 0),
(754, 1, '2025-11-10 11:03:43', '2025-11-10 11:03:43', '<!-- wp:carbon-fields/container-main-screen {\"data\":{\"dolphincargo_container_main_screen_title\":\"ТИПИ ТА РОЗМІРИ МОРСЬКИХ \\u2028КОНТЕЙНЕРІВ\",\"dolphincargo_container_main_screen_who_are_we\":\"Підберемо оптимальний формат контейнеру під ваш вантаж, розрахуємо вартість доставки та забезпечимо повний логістичний супровід\",\"dolphincargo_container_main_screen_image\":\"http://dolphincargo.loc/wp-content/uploads/2025/02/fon-5_optimized-scaled.jpg\",\"dolphincargo_container_main_screen_image_larg\":\"http://dolphincargo.loc/wp-content/uploads/2025/02/fon-5_optimized-scaled.jpg\",\"dolphincargo_container_main_screen_image_mob\":\"http://dolphincargo.loc/wp-content/uploads/2025/02/fon-5_optimized-scaled.jpg\",\"dolphincargo_container_main_screen_advantages_list\":[{\"_id\":\"cf-EI3HxdhpjI7uTto2Xa_SM\",\"_type\":\"_\",\"name\":\"Найвигідніші варіанти доставки для вашого об’єму й типу вантажу\"},{\"_id\":\"cf-uBxA6kN34sEwijDCism0Y\",\"_type\":\"_\",\"name\":\"Без прихованих платежів, фіксований тариф \\u2028з реальними термінами\"},{\"_id\":\"cf-BuAbLfYB3ozwadfssfs3s\",\"_type\":\"_\",\"name\":\"Повний супровід контейнера — від завантаження до митного оформлення в Україні\"}]}} /-->\n\n<!-- wp:carbon-fields/more-choice-lessl-cost {\"data\":{\"dolphincargo_taobao_more_choice_title\":\"Ваш вантаж — під повним\\u003c/br\\u003e контролем від Китаю до України\",\"dolphincargo_taobao_more_choice_text\":\"\\u003cp\\u003eМорські контейнери — це універсальна й надійна тара, що використовується у міжнародній логістиці для транспортування вантажів різного типу.\\u003c/p\\u003e\",\"block_image\":734,\"dolphincargo_taobao_more_choice_list\":[{\"_id\":\"cf-7y6tRv8hdUzpQUP8Llym9\",\"_type\":\"_\",\"text\":\"Правильно обрані типи морських контейнерів забезпечують безпеку товару, оптимізують простір і допомагають зменшити вартість доставки.\"},{\"_id\":\"cf-7Zbw9W_stGPahJSQPBNxJ\",\"_type\":\"_\",\"text\":\"Dolphin Cargo спеціалізується на перевезеннях морських контейнерів з Китаю та Європи, підбираючи рішення під кожен маршрут, бюджет і об’єм.\"},{\"_id\":\"cf-GyTJPNzEPnv29Cu32v9Zn\",\"_type\":\"_\",\"text\":\"Наші клієнти отримують точні розрахунки, стабільні терміни та впевненість, що вантаж прибуде без пошкоджень і затримок.\"}]}} /-->\n\n<!-- wp:carbon-fields/container-call-to-action {\"data\":{\"dolphincargo_title\":\"НЕ ХОЧЕТЕ ВИТРАЧАТИ ЧАС \\u003cbr\\u003eНА ДЕТАЛІ ТА РИЗИКУВАТИ?\",\"dolphincargo_text\":\"\\u003cp\\u003eМи беремо все на себе: підбір контейнера, документи, митницю, доставку.\\u003cbr /\\u003eПросто залиште заявку — і ми запустимо процес вже сьогодні.\\u003c/p\\u003e\",\"dolphincargo_image\":744}} /-->\n\n<!-- wp:carbon-fields/why-choose-us {\"data\":{\"dolphincargo_block_problem_title\":\"ЧОМУ ОБИРАЮТЬ НАС\",\"dolphincargo_block_problem_list\":[{\"_id\":\"cf-4JfcpqAmsSonh4PWOap2O\",\"_type\":\"_\",\"name\":\"Без посередників і переплат\",\"reason_list\":[{\"_id\":\"cf-0SQOhi2_yMcg5tqU9vrtP\",\"_type\":\"_\",\"text\":\"\\u003cp\\u003eМи працюємо напряму з китайськими портами та судноплавними лініями, тому вартість перевезення морських контейнерів безкомпромісно залишається прозорою і конкурентною.\\u2028Жодних додаткових націнок — лише реальні тарифи та фіксовані умови доставки.\\u003c/p\\u003e\"}]},{\"_id\":\"cf-831JqpA2N8VggAzL0fcmk\",\"_type\":\"_\",\"name\":\"Повний контроль на кожному етапі\",\"reason_list\":[{\"_id\":\"cf-opB9_tnUGnb4Cbrdi3rKt\",\"_type\":\"_\",\"text\":\"\\u003cp\\u003eМи відстежуємо контейнер із моменту завантаження в Китаї до прибуття в Україну.\\u2028Наші клієнти бачать статус вантажу в своєму особистому кабінеті.\\u2028Ваш морський контейнер з Китаю цілодобово під контролем нашої команди.\\u003c/p\\u003e\"}]},{\"_id\":\"cf-l1P4SLLgfPPYYEtpa1nbw\",\"_type\":\"_\",\"name\":\"Збірні контейнери — вигідне рішення для малих партій\",\"reason_list\":[{\"_id\":\"cf-FH6eMJWSdoCqd4rgmqDtB\",\"_type\":\"_\",\"text\":\"\\u003cp\\u003eНе обов’язково чекати на повне завантаження. Ми об’єднуємо ваш вантаж із іншими нашими клієнтами в збірні контейнери з Китаю, щоб ви платили лише за свій об’єм.\\u2028Ідеальне рішення для малого бізнесу та тестових партій.\\u003c/p\\u003e\"}]},{\"_id\":\"cf-fybsD0uESzl0ZLNOHfydk\",\"_type\":\"_\",\"name\":\"Сервіс під ключ — від розрахунку до митного оформлення\",\"reason_list\":[{\"_id\":\"cf-L8KwsgrnmWazD3xNrgRyP\",\"_type\":\"_\",\"text\":\"\\u003cp\\u003eМи беремо на себе всі клопоти: розрахунок вартості, вибір маршруту, підготовку документів і митне очищення в Україні.\\u2028Ви просто отримуєте вантаж — без черг, зайвої бюрократії й непередбачених витрат в підсумку.\\u003c/p\\u003e\"}]}]}} /-->\n\n<!-- wp:carbon-fields/reviews-block {\"data\":{\"dolphincargo_block_reviews_title\":\"ВІДГУКИ НАШИХ КЛІЄНТІВ\"}} /-->\n\n<!-- wp:carbon-fields/faq-block {\"data\":{\"dolphincargo_block_faq_title\":\"Питання та вiдповiдi\",\"dolphincargo_block_faq_list\":[{\"_id\":\"cf-nvd3SsKtefGPz1jJ0R0sY\",\"_type\":\"_\",\"question\":\"Скільки коштує перевезення морських контейнерів з Китаю?\",\"answer\":\"Вартість залежить від маршруту, типу контейнера та ваги вантажу.\\u2028Ми працюємо без посередників, тому пропонуємо чесні тарифи та детальний прорахунок — без “прихованих” комісій.\\u2028Щоб дізнатися точну суму, залиште заявку на сайті — наш менеджер розрахує доставку з урахуванням розмірів морського контейнера, типу вантажу й термінів.\"},{\"_id\":\"cf-qrXFbN8FxokqF396ThxoT\",\"_type\":\"_\",\"question\":\"Які бувають типи морських контейнерів і який обрати?\",\"answer\":\"\\u003cp\\u003eІснують різні типи контейнерів та їх класифікація: стандартні (Dry), підвищеної висоти (High Cube), рефрижераторні (Reefer), відкриті (Open Top, Flat Rack) та для рідин (Tank).\\u2028Якщо вага або обсяг невеликі, радимо скористатися збірним контейнером з Китаю Dolphin Cargo — це дає можливість об’єднати декілька відправлень і зменшити витрати.\\u003c/p\\u003e\"},{\"_id\":\"cf-OGKZNAaxVoCh0zzEx26Zg\",\"_type\":\"_\",\"question\":\"Які стандартні розміри морських контейнерів використовуються найчастіше?\",\"answer\":\"\\u003cp\\u003eУ міжнародній логістиці найпопулярніші — 20-футові та 40-футові моделі.\\u2028Розміри цих контейнерів стандартизовані: 20 ft має довжину 6,06 м і об’єм 33 м³, а 40 ft — довжину 12,19 м і об’єм 67–76 м³.\\u2028Ми допоможемо визначити, який формат вигідніший саме для вашого вантажу.\\u003c/p\\u003e\"},{\"_id\":\"cf-xQFIWPhQCQ0MQwkj2ecrw\",\"_type\":\"_\",\"question\":\"Що входить у послугу перевезення морського контейнера?\",\"answer\":\"\\u003cp\\u003eМи забезпечуємо повний цикл: підбір контейнера, бронювання місця на судні, оформлення документів у Китаї, доставку до України й митне очищення.\\u2028Ви отримуєте готове рішення “під ключ” — без зайвих етапів і посередників.\\u003c/p\\u003e\"},{\"_id\":\"cf-RrdJkNGgypSMLVZtbfpJo\",\"_type\":\"_\",\"question\":\"Скільки триває доставка морем з Китаю?\",\"answer\":\"\\u003cp\\u003eСередній термін — від 30 до 45 днів залежно від маршруту та порту відправлення.\\u2028Ми постійно моніторимо судноплавні лінії, тому підбираємо найшвидший варіант з урахуванням ваших побажань.\\u003c/p\\u003e\"},{\"_id\":\"cf-7NXbRp7NYfy9rRFbA_Nkn\",\"_type\":\"_\",\"question\":\"Як підготувати вантаж до перевезення морським контейнером?\",\"answer\":\"\\u003cp\\u003eЩоб доставка пройшла безпечно, важливо правильно підготувати товар до завантаження.\\u2028Усі предмети мають бути надійно упаковані — у палети, коробки або дерев’яні ящики, з відповідними позначеннями.\\u2028Ми враховуємо особливості вантажу: його пакування, необхідність вентиляції та формати розміщення, щоб уникнути пошкоджень під час перевезення морських контейнерів.\\u003c/p\\u003e\"},{\"_id\":\"cf-a2Z6tpHumYVRgapkpjaFO\",\"_type\":\"_\",\"question\":\"Чи можна об’єднати декілька відправлень у один контейнер?\",\"answer\":\"\\u003cp\\u003eТак, це один із найпопулярніших форматів доставки.\\u2028Ми пропонуємо збірні контейнери з Китаю, де декілька клієнтів ділять місце в одному контейнері та оплачують лише свій об’єм.\\u2028Це дозволяє суттєво зменшити витрати, не очікуючи повного завантаження.\\u2028Dolphin Cargo контролює процес консолідації вантажів і гарантує безпечне розміщення кожної партії.\\u003c/p\\u003e\"},{\"_id\":\"cf-xE63h6GjfAhxcaPJ1Kcvm\",\"_type\":\"_\",\"question\":\"Які документи потрібні для перевезення морського контейнера?\",\"answer\":\"\\u003cp\\u003eДля міжнародних перевезень зазвичай потрібні:\\u003c/p\\u003e\\u003cul role=\\u0022list\\u0022\\u003e\\u003cli\\u003eкомерційний інвойс;\\u003c/li\\u003e\\u003cli\\u003eпакувальний лист;\\u003c/li\\u003e\\u003cli\\u003eсертифікати походження або якості (за потреби);\\u003c/li\\u003e\\u003cli\\u003eконосамент (Bill of Lading).\\u2028\\u2028Ми беремо на себе підготовку всіх транспортних документів і перевірку правильності заповнення.\\u2028Клієнт отримує від нас повний пакет для митного оформлення в Україні — без ризику затримок чи штрафів.\\u003c/li\\u003e\\u003c/ul\\u003e\"}]}} /-->\n\n<!-- wp:carbon-fields/container-how-order {\"data\":{\"dolphincargo_title\":\"ЯК ОБРАТИ КОНТЕЙНЕР\",\"dolphincargo_subtitle\":\"Вибір правильного контейнера — ваш ключ до оптимальної логістики\",\"dolphincargo_top_list\":[{\"_id\":\"cf-rUJBaX7OuDizChuB0PDa9\",\"_type\":\"_\",\"description\":\"Наші логісти враховують вагу, габарити, тип продукції, маршрут і спосіб транспортування, щоб гарантувати вам повну безпеку перевезення.\"},{\"_id\":\"cf-s80ZKNfPS47Y2F0bNvhZX\",\"_type\":\"_\",\"description\":\"Від вибору контейнера залежить не лише вартість морських перевезень, а й терміни доставки, збереження товару та простота митного оформлення.\"},{\"_id\":\"cf-STPYCJtUPNasoZs5i2uNk\",\"_type\":\"_\",\"description\":\"Фахівці Dolphin Cargo підбирають оптимальні рішення — від стандартного контейнера до специфічних вантажів.\"}],\"dolphincargo_big_image\":\"\",\"dolphincargo_small_image\":\"\",\"dolphincargo_list\":[{\"_id\":\"cf-oZjtRZ4RqacafJyPbhkM6\",\"_type\":\"_\",\"name\":\"Враховуйте об’єм \\u2028і вагу вантажу\",\"description\":\"Якщо контейнер буде заповнений не повністю — ви переплачуєте за “повітря”. Якщо перевищите норму — можливі штрафи або затримки.\"},{\"_id\":\"cf-uGvSasn8XY4OTNK2mzgrx\",\"_type\":\"_\",\"name\":\"Аналізуйте маршрут перевезення\",\"description\":\"Для морських маршрутів з Китаю важливо враховувати спиввідношення клімату та специфіки вантажу. Це впливає на вибір між стандартним і рефрижераторним контейнером.\"},{\"_id\":\"cf-I2UQcf4b1lOkHA2vvWhLE\",\"_type\":\"_\",\"name\":\"Оберіть тип пакування\",\"description\":\"Якщо товар чутливий до вологості або пилу — потрібен герметичний контейнер із вентиляцією.\"},{\"_id\":\"cf-HGNlphmQwVE8wPWbuHPqB\",\"_type\":\"_\",\"name\":\"Перевірте умови завантаження та розвантаження\",\"description\":\"Деякі термінали не приймають open top або flat rack — ми завжди перевіряємо це заздалегідь.\"},{\"_id\":\"cf-kQNmxqmfb61vauqz2fibq\",\"_type\":\"_\",\"name\":\"План обігу тари\",\"description\":\"Якщо контейнер потрібно повернути у певний порт — спеціалісти Dolphin Cargo допоможуть організувати логістику порожньої тари\"}]}} /-->', 'ТИПИ ТА РОЗМІРИ МОРСЬКИХ  КОНТЕЙНЕРІВ', '', 'inherit', 'closed', 'closed', '', '724-revision-v1', '', '', '2025-11-10 11:03:43', '2025-11-10 11:03:43', '', 724, 'http://dolphincargo.loc/?p=754', 0, 'revision', '', 0);
КОНТЕЙНЕРІВ', '', 'inherit', 'closed', 'closed', '', '724-revision-v1', '', '', '2025-11-10 11:19:21', '2025-11-10 11:19:21', '', 724, 'http://dolphincargo.loc/?p=755', 0, 'revision', '', 0),
(757, 1, '2025-11-10 12:24:56', '2025-11-10 12:24:56', '<!-- wp:carbon-fields/container-main-screen {\"data\":{\"dolphincargo_container_main_screen_title\":\"ТИПИ ТА РОЗМІРИ МОРСЬКИХ \\u2028КОНТЕЙНЕРІВ\",\"dolphincargo_container_main_screen_who_are_we\":\"Підберемо оптимальний формат контейнеру під ваш вантаж, розрахуємо вартість доставки та забезпечимо повний логістичний супровід\",\"dolphincargo_container_main_screen_image\":\"http://dolphincargo.loc/wp-content/uploads/2025/02/fon-5_optimized-scaled.jpg\",\"dolphincargo_container_main_screen_image_larg\":\"http://dolphincargo.loc/wp-content/uploads/2025/02/fon-5_optimized-scaled.jpg\",\"dolphincargo_container_main_screen_image_mob\":\"http://dolphincargo.loc/wp-content/uploads/2025/02/fon-5_optimized-scaled.jpg\",\"dolphincargo_container_main_screen_advantages_list\":[{\"_id\":\"cf-EI3HxdhpjI7uTto2Xa_SM\",\"_type\":\"_\",\"name\":\"Найвигідніші варіанти доставки для вашого об’єму й типу вантажу\"},{\"_id\":\"cf-uBxA6kN34sEwijDCism0Y\",\"_type\":\"_\",\"name\":\"Без прихованих платежів, фіксований тариф \\u2028з реальними термінами\"},{\"_id\":\"cf-BuAbLfYB3ozwadfssfs3s\",\"_type\":\"_\",\"name\":\"Повний супровід контейнера — від завантаження до митного оформлення в Україні\"}]}} /-->\n\n<!-- wp:carbon-fields/more-choice-lessl-cost {\"data\":{\"dolphincargo_taobao_more_choice_title\":\"Ваш вантаж — під повним\\u003c/br\\u003e контролем від Китаю до України\",\"dolphincargo_taobao_more_choice_text\":\"\\u003cp\\u003eМорські контейнери — це універсальна й надійна тара, що використовується у міжнародній логістиці для транспортування вантажів різного типу.\\u003c/p\\u003e\",\"block_image\":734,\"dolphincargo_taobao_more_choice_list\":[{\"_id\":\"cf-7y6tRv8hdUzpQUP8Llym9\",\"_type\":\"_\",\"text\":\"Правильно обрані типи морських контейнерів забезпечують безпеку товару, оптимізують простір і допомагають зменшити вартість доставки.\"},{\"_id\":\"cf-7Zbw9W_stGPahJSQPBNxJ\",\"_type\":\"_\",\"text\":\"Dolphin Cargo спеціалізується на перевезеннях морських контейнерів з Китаю та Європи, підбираючи рішення під кожен маршрут, бюджет і об’єм.\"},{\"_id\":\"cf-GyTJPNzEPnv29Cu32v9Zn\",\"_type\":\"_\",\"text\":\"Наші клієнти отримують точні розрахунки, стабільні терміни та впевненість, що вантаж прибуде без пошкоджень і затримок.\"}]}} /-->\n\n<!-- wp:carbon-fields/container-sizes-volumes {\"data\":{\"dolphincargo_title\":\"РОЗМІРИ ТА ОБ’ЄМИ КОНТЕЙНЕРІВ\",\"dolphincargo_about_containers\":\"\\u003cp\\u003eСтандартизовані розміри контейнерів полегшують завантаження, облік і транспортування — тому більшість компаній у світі працюють із моделями на 20 і 40 футів.\\u003c/p\\u003e\\n\\u003cp\\u003eМи допоможемо визначити, який морський контейнер розміри підходить саме для вашого вантажу.\\u003c/p\\u003e\",\"dolphincargo_offer\":\"\\u003cp\\u003eЯкщо ваш вантаж не заповнює контейнер повністю, Dolphin Cargo пропонує рішення — збірні контейнери з Китаю. Це дозволяє відправляти невеликі партії разом із вантажами інших клієнтів і зменшувати витрати на доставку без втрати швидкості.\\u003c/p\\u003e\",\"dolphincargo_list\":[{\"_id\":\"cf-8eWPQPMDVYsnOY2tPMzLY\",\"_type\":\"_\",\"name\":\"20 FT контейнер\",\"length\":\"6,06 м\",\"width\":\"2,44 м\",\"volume_height\":\"33 м³\",\"empty_weight\":\"2,2 т\",\"load_capacity\":\"до 30 т\"},{\"_id\":\"cf-EvuaS3l13hwElD0KJtbzM\",\"_type\":\"_\",\"name\":\"40 FT контейнер\",\"length\":\"12,19 м\",\"width\":\"2,44 м\",\"volume_height\":\"2,89 м\",\"empty_weight\":\"3,8–4,2 т\",\"load_capacity\":\"до 30 т\"}]}} /-->\n\n<!-- wp:carbon-fields/container-how-order {\"data\":{\"dolphincargo_title\":\"ЯК ОБРАТИ КОНТЕЙНЕР\",\"dolphincargo_subtitle\":\"Вибір правильного контейнера — ваш ключ до оптимальної логістики\",\"dolphincargo_top_list\":[{\"_id\":\"cf-rUJBaX7OuDizChuB0PDa9\",\"_type\":\"_\",\"description\":\"Наші логісти враховують вагу, габарити, тип продукції, маршрут і спосіб транспортування, щоб гарантувати вам повну безпеку перевезення.\"},{\"_id\":\"cf-s80ZKNfPS47Y2F0bNvhZX\",\"_type\":\"_\",\"description\":\"Від вибору контейнера залежить не лише вартість морських перевезень, а й терміни доставки, збереження товару та простота митного оформлення.\"},{\"_id\":\"cf-STPYCJtUPNasoZs5i2uNk\",\"_type\":\"_\",\"description\":\"Фахівці Dolphin Cargo підбирають оптимальні рішення — від стандартного контейнера до специфічних вантажів.\"}],\"dolphincargo_big_image\":\"\",\"dolphincargo_small_image\":\"\",\"dolphincargo_list\":[{\"_id\":\"cf-oZjtRZ4RqacafJyPbhkM6\",\"_type\":\"_\",\"name\":\"Враховуйте об’єм \\u2028і вагу вантажу\",\"description\":\"Якщо контейнер буде заповнений не повністю — ви переплачуєте за “повітря”. Якщо перевищите норму — можливі штрафи або затримки.\"},{\"_id\":\"cf-uGvSasn8XY4OTNK2mzgrx\",\"_type\":\"_\",\"name\":\"Аналізуйте маршрут перевезення\",\"description\":\"Для морських маршрутів з Китаю важливо враховувати спиввідношення клімату та специфіки вантажу. Це впливає на вибір між стандартним і рефрижераторним контейнером.\"},{\"_id\":\"cf-I2UQcf4b1lOkHA2vvWhLE\",\"_type\":\"_\",\"name\":\"Оберіть тип пакування\",\"description\":\"Якщо товар чутливий до вологості або пилу — потрібен герметичний контейнер із вентиляцією.\"},{\"_id\":\"cf-HGNlphmQwVE8wPWbuHPqB\",\"_type\":\"_\",\"name\":\"Перевірте умови завантаження та розвантаження\",\"description\":\"Деякі термінали не приймають open top або flat rack — ми завжди перевіряємо це заздалегідь.\"},{\"_id\":\"cf-kQNmxqmfb61vauqz2fibq\",\"_type\":\"_\",\"name\":\"План обігу тари\",\"description\":\"Якщо контейнер потрібно повернути у певний порт — спеціалісти Dolphin Cargo допоможуть організувати логістику порожньої тари\"}]}} /-->\n\n<!-- wp:carbon-fields/container-call-to-action {\"data\":{\"dolphincargo_title\":\"НЕ ХОЧЕТЕ ВИТРАЧАТИ ЧАС \\u003cbr\\u003eНА ДЕТАЛІ ТА РИЗИКУВАТИ?\",\"dolphincargo_text\":\"\\u003cp\\u003eМи беремо все на себе: підбір контейнера, документи, митницю, доставку.\\u003cbr /\\u003eПросто залиште заявку — і ми запустимо процес вже сьогодні.\\u003c/p\\u003e\",\"dolphincargo_image\":744}} /-->\n\n<!-- wp:carbon-fields/why-choose-us {\"data\":{\"dolphincargo_block_problem_title\":\"ЧОМУ ОБИРАЮТЬ НАС\",\"dolphincargo_block_problem_list\":[{\"_id\":\"cf-4JfcpqAmsSonh4PWOap2O\",\"_type\":\"_\",\"name\":\"Без посередників і переплат\",\"reason_list\":[{\"_id\":\"cf-0SQOhi2_yMcg5tqU9vrtP\",\"_type\":\"_\",\"text\":\"\\u003cp\\u003eМи працюємо напряму з китайськими портами та судноплавними лініями, тому вартість перевезення морських контейнерів безкомпромісно залишається прозорою і конкурентною.\\u2028Жодних додаткових націнок — лише реальні тарифи та фіксовані умови доставки.\\u003c/p\\u003e\"}]},{\"_id\":\"cf-831JqpA2N8VggAzL0fcmk\",\"_type\":\"_\",\"name\":\"Повний контроль на кожному етапі\",\"reason_list\":[{\"_id\":\"cf-opB9_tnUGnb4Cbrdi3rKt\",\"_type\":\"_\",\"text\":\"\\u003cp\\u003eМи відстежуємо контейнер із моменту завантаження в Китаї до прибуття в Україну.\\u2028Наші клієнти бачать статус вантажу в своєму особистому кабінеті.\\u2028Ваш морський контейнер з Китаю цілодобово під контролем нашої команди.\\u003c/p\\u003e\"}]},{\"_id\":\"cf-l1P4SLLgfPPYYEtpa1nbw\",\"_type\":\"_\",\"name\":\"Збірні контейнери — вигідне рішення для малих партій\",\"reason_list\":[{\"_id\":\"cf-FH6eMJWSdoCqd4rgmqDtB\",\"_type\":\"_\",\"text\":\"\\u003cp\\u003eНе обов’язково чекати на повне завантаження. Ми об’єднуємо ваш вантаж із іншими нашими клієнтами в збірні контейнери з Китаю, щоб ви платили лише за свій об’єм.\\u2028Ідеальне рішення для малого бізнесу та тестових партій.\\u003c/p\\u003e\"}]},{\"_id\":\"cf-fybsD0uESzl0ZLNOHfydk\",\"_type\":\"_\",\"name\":\"Сервіс під ключ — від розрахунку до митного оформлення\",\"reason_list\":[{\"_id\":\"cf-L8KwsgrnmWazD3xNrgRyP\",\"_type\":\"_\",\"text\":\"\\u003cp\\u003eМи беремо на себе всі клопоти: розрахунок вартості, вибір маршруту, підготовку документів і митне очищення в Україні.\\u2028Ви просто отримуєте вантаж — без черг, зайвої бюрократії й непередбачених витрат в підсумку.\\u003c/p\\u003e\"}]}]}} /-->\n\n<!-- wp:carbon-fields/reviews-block {\"data\":{\"dolphincargo_block_reviews_title\":\"ВІДГУКИ НАШИХ КЛІЄНТІВ\"}} /-->\n\n<!-- wp:carbon-fields/faq-block {\"data\":{\"dolphincargo_block_faq_title\":\"Питання та вiдповiдi\",\"dolphincargo_block_faq_list\":[{\"_id\":\"cf-nvd3SsKtefGPz1jJ0R0sY\",\"_type\":\"_\",\"question\":\"Скільки коштує перевезення морських контейнерів з Китаю?\",\"answer\":\"Вартість залежить від маршруту, типу контейнера та ваги вантажу.\\u2028Ми працюємо без посередників, тому пропонуємо чесні тарифи та детальний прорахунок — без “прихованих” комісій.\\u2028Щоб дізнатися точну суму, залиште заявку на сайті — наш менеджер розрахує доставку з урахуванням розмірів морського контейнера, типу вантажу й термінів.\"},{\"_id\":\"cf-qrXFbN8FxokqF396ThxoT\",\"_type\":\"_\",\"question\":\"Які бувають типи морських контейнерів і який обрати?\",\"answer\":\"\\u003cp\\u003eІснують різні типи контейнерів та їх класифікація: стандартні (Dry), підвищеної висоти (High Cube), рефрижераторні (Reefer), відкриті (Open Top, Flat Rack) та для рідин (Tank).\\u2028Якщо вага або обсяг невеликі, радимо скористатися збірним контейнером з Китаю Dolphin Cargo — це дає можливість об’єднати декілька відправлень і зменшити витрати.\\u003c/p\\u003e\"},{\"_id\":\"cf-OGKZNAaxVoCh0zzEx26Zg\",\"_type\":\"_\",\"question\":\"Які стандартні розміри морських контейнерів використовуються найчастіше?\",\"answer\":\"\\u003cp\\u003eУ міжнародній логістиці найпопулярніші — 20-футові та 40-футові моделі.\\u2028Розміри цих контейнерів стандартизовані: 20 ft має довжину 6,06 м і об’єм 33 м³, а 40 ft — довжину 12,19 м і об’єм 67–76 м³.\\u2028Ми допоможемо визначити, який формат вигідніший саме для вашого вантажу.\\u003c/p\\u003e\"},{\"_id\":\"cf-xQFIWPhQCQ0MQwkj2ecrw\",\"_type\":\"_\",\"question\":\"Що входить у послугу перевезення морського контейнера?\",\"answer\":\"\\u003cp\\u003eМи забезпечуємо повний цикл: підбір контейнера, бронювання місця на судні, оформлення документів у Китаї, доставку до України й митне очищення.\\u2028Ви отримуєте готове рішення “під ключ” — без зайвих етапів і посередників.\\u003c/p\\u003e\"},{\"_id\":\"cf-RrdJkNGgypSMLVZtbfpJo\",\"_type\":\"_\",\"question\":\"Скільки триває доставка морем з Китаю?\",\"answer\":\"\\u003cp\\u003eСередній термін — від 30 до 45 днів залежно від маршруту та порту відправлення.\\u2028Ми постійно моніторимо судноплавні лінії, тому підбираємо найшвидший варіант з урахуванням ваших побажань.\\u003c/p\\u003e\"},{\"_id\":\"cf-7NXbRp7NYfy9rRFbA_Nkn\",\"_type\":\"_\",\"question\":\"Як підготувати вантаж до перевезення морським контейнером?\",\"answer\":\"\\u003cp\\u003eЩоб доставка пройшла безпечно, важливо правильно підготувати товар до завантаження.\\u2028Усі предмети мають бути надійно упаковані — у палети, коробки або дерев’яні ящики, з відповідними позначеннями.\\u2028Ми враховуємо особливості вантажу: його пакування, необхідність вентиляції та формати розміщення, щоб уникнути пошкоджень під час перевезення морських контейнерів.\\u003c/p\\u003e\"},{\"_id\":\"cf-a2Z6tpHumYVRgapkpjaFO\",\"_type\":\"_\",\"question\":\"Чи можна об’єднати декілька відправлень у один контейнер?\",\"answer\":\"\\u003cp\\u003eТак, це один із найпопулярніших форматів доставки.\\u2028Ми пропонуємо збірні контейнери з Китаю, де декілька клієнтів ділять місце в одному контейнері та оплачують лише свій об’єм.\\u2028Це дозволяє суттєво зменшити витрати, не очікуючи повного завантаження.\\u2028Dolphin Cargo контролює процес консолідації вантажів і гарантує безпечне розміщення кожної партії.\\u003c/p\\u003e\"},{\"_id\":\"cf-xE63h6GjfAhxcaPJ1Kcvm\",\"_type\":\"_\",\"question\":\"Які документи потрібні для перевезення морського контейнера?\",\"answer\":\"\\u003cp\\u003eДля міжнародних перевезень зазвичай потрібні:\\u003c/p\\u003e\\u003cul role=\\u0022list\\u0022\\u003e\\u003cli\\u003eкомерційний інвойс;\\u003c/li\\u003e\\u003cli\\u003eпакувальний лист;\\u003c/li\\u003e\\u003cli\\u003eсертифікати походження або якості (за потреби);\\u003c/li\\u003e\\u003cli\\u003eконосамент (Bill of Lading).\\u2028\\u2028Ми беремо на себе підготовку всіх транспортних документів і перевірку правильності заповнення.\\u2028Клієнт отримує від нас повний пакет для митного оформлення в Україні — без ризику затримок чи штрафів.\\u003c/li\\u003e\\u003c/ul\\u003e\"}]}} /-->', 'ТИПИ ТА РОЗМІРИ МОРСЬКИХ  КОНТЕЙНЕРІВ', '', 'inherit', 'closed', 'closed', '', '724-revision-v1', '', '', '2025-11-10 12:24:56', '2025-11-10 12:24:56', '', 724, 'http://dolphincargo.loc/?p=757', 0, 'revision', '', 0),
(759, 1, '2025-11-10 15:05:29', '2025-11-10 15:05:29', '<!-- wp:carbon-fields/container-main-screen {\"data\":{\"dolphincargo_container_main_screen_title\":\"ТИПИ ТА РОЗМІРИ МОРСЬКИХ \\u2028КОНТЕЙНЕРІВ\",\"dolphincargo_container_main_screen_who_are_we\":\"Підберемо оптимальний формат контейнеру під ваш вантаж, розрахуємо вартість доставки та забезпечимо повний логістичний супровід\",\"dolphincargo_container_main_screen_image\":\"http://dolphincargo.loc/wp-content/uploads/2025/02/fon-5_optimized-scaled.jpg\",\"dolphincargo_container_main_screen_image_larg\":\"http://dolphincargo.loc/wp-content/uploads/2025/02/fon-5_optimized-scaled.jpg\",\"dolphincargo_container_main_screen_image_mob\":\"http://dolphincargo.loc/wp-content/uploads/2025/02/fon-5_optimized-scaled.jpg\",\"dolphincargo_container_main_screen_advantages_list\":[{\"_id\":\"cf-EI3HxdhpjI7uTto2Xa_SM\",\"_type\":\"_\",\"name\":\"Найвигідніші варіанти доставки для вашого об’єму й типу вантажу\"},{\"_id\":\"cf-uBxA6kN34sEwijDCism0Y\",\"_type\":\"_\",\"name\":\"Без прихованих платежів, фіксований тариф \\u2028з реальними термінами\"},{\"_id\":\"cf-BuAbLfYB3ozwadfssfs3s\",\"_type\":\"_\",\"name\":\"Повний супровід контейнера — від завантаження до митного оформлення в Україні\"}]}} /-->\n\n<!-- wp:carbon-fields/more-choice-lessl-cost {\"data\":{\"dolphincargo_taobao_more_choice_title\":\"Ваш вантаж — під повним\\u003c/br\\u003e контролем від Китаю до України\",\"dolphincargo_taobao_more_choice_text\":\"\\u003cp\\u003eМорські контейнери — це універсальна й надійна тара, що використовується у міжнародній логістиці для транспортування вантажів різного типу.\\u003c/p\\u003e\",\"block_image\":734,\"dolphincargo_taobao_more_choice_list\":[{\"_id\":\"cf-7y6tRv8hdUzpQUP8Llym9\",\"_type\":\"_\",\"text\":\"Правильно обрані типи морських контейнерів забезпечують безпеку товару, оптимізують простір і допомагають зменшити вартість доставки.\"},{\"_id\":\"cf-7Zbw9W_stGPahJSQPBNxJ\",\"_type\":\"_\",\"text\":\"Dolphin Cargo спеціалізується на перевезеннях морських контейнерів з Китаю та Європи, підбираючи рішення під кожен маршрут, бюджет і об’єм.\"},{\"_id\":\"cf-GyTJPNzEPnv29Cu32v9Zn\",\"_type\":\"_\",\"text\":\"Наші клієнти отримують точні розрахунки, стабільні терміни та впевненість, що вантаж прибуде без пошкоджень і затримок.\"}]}} /-->\n\n<!-- wp:carbon-fields/container-types {\"data\":{\"dolphincargo_title\":\"ТИПИ МОРСЬКИХ КОНТЕЙНЕРІВ\",\"dolphincargo_list\":[{\"_id\":\"cf-AJpFXJ0K8hetGe6FivcTQ\",\"_type\":\"_\",\"name_tab\":\"Dry Container (DC)\",\"image\":\"\",\"title\":\"\",\"description\":\"\",\"for_list\":[],\"advantage\":\"\"},{\"_id\":\"cf-gNQr7N7ONsKVlBUvxNl02\",\"_type\":\"_\",\"name_tab\":\"High Cube (HC)\",\"image\":\"\",\"title\":\"\",\"description\":\"\",\"for_list\":[],\"advantage\":\"\"},{\"_id\":\"cf-sqmCDhf3czYe8361Pylue\",\"_type\":\"_\",\"name_tab\":\"Reefer Container (RF)\",\"image\":\"\",\"title\":\"\",\"description\":\"\",\"for_list\":[],\"advantage\":\"\"},{\"_id\":\"cf-pFHGOqFm7Nnl572xySW_V\",\"_type\":\"_\",\"name_tab\":\"Open Top (OT)\",\"image\":\"\",\"title\":\"\",\"description\":\"\",\"for_list\":[],\"advantage\":\"\"},{\"_id\":\"cf-enQznvXyJAqDwOSdiMSkf\",\"_type\":\"_\",\"name_tab\":\"Flat Rack (FR)\",\"image\":\"\",\"title\":\"\",\"description\":\"\",\"for_list\":[],\"advantage\":\"\"},{\"_id\":\"cf-vwLueuP7_IXtypXdmIc6w\",\"_type\":\"_\",\"name_tab\":\"Tank Container (TK)\",\"image\":\"\",\"title\":\"\",\"description\":\"\",\"for_list\":[],\"advantage\":\"\"}]}} /-->\n\n<!-- wp:carbon-fields/container-sizes-volumes {\"data\":{\"dolphincargo_title\":\"РОЗМІРИ ТА ОБ’ЄМИ КОНТЕЙНЕРІВ\",\"dolphincargo_about_containers\":\"\\u003cp\\u003eСтандартизовані розміри контейнерів полегшують завантаження, облік і транспортування — тому більшість компаній у світі працюють із моделями на 20 і 40 футів.\\u003c/p\\u003e\\n\\u003cp\\u003eМи допоможемо визначити, який морський контейнер розміри підходить саме для вашого вантажу.\\u003c/p\\u003e\",\"dolphincargo_offer\":\"\\u003cp\\u003eЯкщо ваш вантаж не заповнює контейнер повністю, Dolphin Cargo пропонує рішення — збірні контейнери з Китаю. Це дозволяє відправляти невеликі партії разом із вантажами інших клієнтів і зменшувати витрати на доставку без втрати швидкості.\\u003c/p\\u003e\",\"dolphincargo_list\":[{\"_id\":\"cf-8eWPQPMDVYsnOY2tPMzLY\",\"_type\":\"_\",\"name\":\"20 FT контейнер\",\"length\":\"6,06 м\",\"width\":\"2,44 м\",\"volume_height\":\"33 м³\",\"empty_weight\":\"2,2 т\",\"load_capacity\":\"до 30 т\"},{\"_id\":\"cf-EvuaS3l13hwElD0KJtbzM\",\"_type\":\"_\",\"name\":\"40 FT контейнер\",\"length\":\"12,19 м\",\"width\":\"2,44 м\",\"volume_height\":\"2,89 м\",\"empty_weight\":\"3,8–4,2 т\",\"load_capacity\":\"до 30 т\"}]}} /-->\n\n<!-- wp:carbon-fields/container-how-order {\"data\":{\"dolphincargo_title\":\"ЯК ОБРАТИ КОНТЕЙНЕР\",\"dolphincargo_subtitle\":\"Вибір правильного контейнера — ваш ключ до оптимальної логістики\",\"dolphincargo_top_list\":[{\"_id\":\"cf-rUJBaX7OuDizChuB0PDa9\",\"_type\":\"_\",\"description\":\"Наші логісти враховують вагу, габарити, тип продукції, маршрут і спосіб транспортування, щоб гарантувати вам повну безпеку перевезення.\"},{\"_id\":\"cf-s80ZKNfPS47Y2F0bNvhZX\",\"_type\":\"_\",\"description\":\"Від вибору контейнера залежить не лише вартість морських перевезень, а й терміни доставки, збереження товару та простота митного оформлення.\"},{\"_id\":\"cf-STPYCJtUPNasoZs5i2uNk\",\"_type\":\"_\",\"description\":\"Фахівці Dolphin Cargo підбирають оптимальні рішення — від стандартного контейнера до специфічних вантажів.\"}],\"dolphincargo_big_image\":\"\",\"dolphincargo_small_image\":\"\",\"dolphincargo_list\":[{\"_id\":\"cf-oZjtRZ4RqacafJyPbhkM6\",\"_type\":\"_\",\"name\":\"Враховуйте об’єм \\u2028і вагу вантажу\",\"description\":\"Якщо контейнер буде заповнений не повністю — ви переплачуєте за “повітря”. Якщо перевищите норму — можливі штрафи або затримки.\"},{\"_id\":\"cf-uGvSasn8XY4OTNK2mzgrx\",\"_type\":\"_\",\"name\":\"Аналізуйте маршрут перевезення\",\"description\":\"Для морських маршрутів з Китаю важливо враховувати спиввідношення клімату та специфіки вантажу. Це впливає на вибір між стандартним і рефрижераторним контейнером.\"},{\"_id\":\"cf-I2UQcf4b1lOkHA2vvWhLE\",\"_type\":\"_\",\"name\":\"Оберіть тип пакування\",\"description\":\"Якщо товар чутливий до вологості або пилу — потрібен герметичний контейнер із вентиляцією.\"},{\"_id\":\"cf-HGNlphmQwVE8wPWbuHPqB\",\"_type\":\"_\",\"name\":\"Перевірте умови завантаження та розвантаження\",\"description\":\"Деякі термінали не приймають open top або flat rack — ми завжди перевіряємо це заздалегідь.\"},{\"_id\":\"cf-kQNmxqmfb61vauqz2fibq\",\"_type\":\"_\",\"name\":\"План обігу тари\",\"description\":\"Якщо контейнер потрібно повернути у певний порт — спеціалісти Dolphin Cargo допоможуть організувати логістику порожньої тари\"}]}} /-->\n\n<!-- wp:carbon-fields/container-call-to-action {\"data\":{\"dolphincargo_title\":\"НЕ ХОЧЕТЕ ВИТРАЧАТИ ЧАС \\u003cbr\\u003eНА ДЕТАЛІ ТА РИЗИКУВАТИ?\",\"dolphincargo_text\":\"\\u003cp\\u003eМи беремо все на себе: підбір контейнера, документи, митницю, доставку.\\u003cbr /\\u003eПросто залиште заявку — і ми запустимо процес вже сьогодні.\\u003c/p\\u003e\",\"dolphincargo_image\":744}} /-->\n\n<!-- wp:carbon-fields/why-choose-us {\"data\":{\"dolphincargo_block_problem_title\":\"ЧОМУ ОБИРАЮТЬ НАС\",\"dolphincargo_block_problem_list\":[{\"_id\":\"cf-4JfcpqAmsSonh4PWOap2O\",\"_type\":\"_\",\"name\":\"Без посередників і переплат\",\"reason_list\":[{\"_id\":\"cf-0SQOhi2_yMcg5tqU9vrtP\",\"_type\":\"_\",\"text\":\"\\u003cp\\u003eМи працюємо напряму з китайськими портами та судноплавними лініями, тому вартість перевезення морських контейнерів безкомпромісно залишається прозорою і конкурентною.\\u2028Жодних додаткових націнок — лише реальні тарифи та фіксовані умови доставки.\\u003c/p\\u003e\"}]},{\"_id\":\"cf-831JqpA2N8VggAzL0fcmk\",\"_type\":\"_\",\"name\":\"Повний контроль на кожному етапі\",\"reason_list\":[{\"_id\":\"cf-opB9_tnUGnb4Cbrdi3rKt\",\"_type\":\"_\",\"text\":\"\\u003cp\\u003eМи відстежуємо контейнер із моменту завантаження в Китаї до прибуття в Україну.\\u2028Наші клієнти бачать статус вантажу в своєму особистому кабінеті.\\u2028Ваш морський контейнер з Китаю цілодобово під контролем нашої команди.\\u003c/p\\u003e\"}]},{\"_id\":\"cf-l1P4SLLgfPPYYEtpa1nbw\",\"_type\":\"_\",\"name\":\"Збірні контейнери — вигідне рішення для малих партій\",\"reason_list\":[{\"_id\":\"cf-FH6eMJWSdoCqd4rgmqDtB\",\"_type\":\"_\",\"text\":\"\\u003cp\\u003eНе обов’язково чекати на повне завантаження. Ми об’єднуємо ваш вантаж із іншими нашими клієнтами в збірні контейнери з Китаю, щоб ви платили лише за свій об’єм.\\u2028Ідеальне рішення для малого бізнесу та тестових партій.\\u003c/p\\u003e\"}]},{\"_id\":\"cf-fybsD0uESzl0ZLNOHfydk\",\"_type\":\"_\",\"name\":\"Сервіс під ключ — від розрахунку до митного оформлення\",\"reason_list\":[{\"_id\":\"cf-L8KwsgrnmWazD3xNrgRyP\",\"_type\":\"_\",\"text\":\"\\u003cp\\u003eМи беремо на себе всі клопоти: розрахунок вартості, вибір маршруту, підготовку документів і митне очищення в Україні.\\u2028Ви просто отримуєте вантаж — без черг, зайвої бюрократії й непередбачених витрат в підсумку.\\u003c/p\\u003e\"}]}]}} /-->\n\n<!-- wp:carbon-fields/reviews-block {\"data\":{\"dolphincargo_block_reviews_title\":\"ВІДГУКИ НАШИХ КЛІЄНТІВ\"}} /-->\n\n<!-- wp:carbon-fields/faq-block {\"data\":{\"dolphincargo_block_faq_title\":\"Питання та вiдповiдi\",\"dolphincargo_block_faq_list\":[{\"_id\":\"cf-nvd3SsKtefGPz1jJ0R0sY\",\"_type\":\"_\",\"question\":\"Скільки коштує перевезення морських контейнерів з Китаю?\",\"answer\":\"Вартість залежить від маршруту, типу контейнера та ваги вантажу.\\u2028Ми працюємо без посередників, тому пропонуємо чесні тарифи та детальний прорахунок — без “прихованих” комісій.\\u2028Щоб дізнатися точну суму, залиште заявку на сайті — наш менеджер розрахує доставку з урахуванням розмірів морського контейнера, типу вантажу й термінів.\"},{\"_id\":\"cf-qrXFbN8FxokqF396ThxoT\",\"_type\":\"_\",\"question\":\"Які бувають типи морських контейнерів і який обрати?\",\"answer\":\"\\u003cp\\u003eІснують різні типи контейнерів та їх класифікація: стандартні (Dry), підвищеної висоти (High Cube), рефрижераторні (Reefer), відкриті (Open Top, Flat Rack) та для рідин (Tank).\\u2028Якщо вага або обсяг невеликі, радимо скористатися збірним контейнером з Китаю Dolphin Cargo — це дає можливість об’єднати декілька відправлень і зменшити витрати.\\u003c/p\\u003e\"},{\"_id\":\"cf-OGKZNAaxVoCh0zzEx26Zg\",\"_type\":\"_\",\"question\":\"Які стандартні розміри морських контейнерів використовуються найчастіше?\",\"answer\":\"\\u003cp\\u003eУ міжнародній логістиці найпопулярніші — 20-футові та 40-футові моделі.\\u2028Розміри цих контейнерів стандартизовані: 20 ft має довжину 6,06 м і об’єм 33 м³, а 40 ft — довжину 12,19 м і об’єм 67–76 м³.\\u2028Ми допоможемо визначити, який формат вигідніший саме для вашого вантажу.\\u003c/p\\u003e\"},{\"_id\":\"cf-xQFIWPhQCQ0MQwkj2ecrw\",\"_type\":\"_\",\"question\":\"Що входить у послугу перевезення морського контейнера?\",\"answer\":\"\\u003cp\\u003eМи забезпечуємо повний цикл: підбір контейнера, бронювання місця на судні, оформлення документів у Китаї, доставку до України й митне очищення.\\u2028Ви отримуєте готове рішення “під ключ” — без зайвих етапів і посередників.\\u003c/p\\u003e\"},{\"_id\":\"cf-RrdJkNGgypSMLVZtbfpJo\",\"_type\":\"_\",\"question\":\"Скільки триває доставка морем з Китаю?\",\"answer\":\"\\u003cp\\u003eСередній термін — від 30 до 45 днів залежно від маршруту та порту відправлення.\\u2028Ми постійно моніторимо судноплавні лінії, тому підбираємо найшвидший варіант з урахуванням ваших побажань.\\u003c/p\\u003e\"},{\"_id\":\"cf-7NXbRp7NYfy9rRFbA_Nkn\",\"_type\":\"_\",\"question\":\"Як підготувати вантаж до перевезення морським контейнером?\",\"answer\":\"\\u003cp\\u003eЩоб доставка пройшла безпечно, важливо правильно підготувати товар до завантаження.\\u2028Усі предмети мають бути надійно упаковані — у палети, коробки або дерев’яні ящики, з відповідними позначеннями.\\u2028Ми враховуємо особливості вантажу: його пакування, необхідність вентиляції та формати розміщення, щоб уникнути пошкоджень під час перевезення морських контейнерів.\\u003c/p\\u003e\"},{\"_id\":\"cf-a2Z6tpHumYVRgapkpjaFO\",\"_type\":\"_\",\"question\":\"Чи можна об’єднати декілька відправлень у один контейнер?\",\"answer\":\"\\u003cp\\u003eТак, це один із найпопулярніших форматів доставки.\\u2028Ми пропонуємо збірні контейнери з Китаю, де декілька клієнтів ділять місце в одному контейнері та оплачують лише свій об’єм.\\u2028Це дозволяє суттєво зменшити витрати, не очікуючи повного завантаження.\\u2028Dolphin Cargo контролює процес консолідації вантажів і гарантує безпечне розміщення кожної партії.\\u003c/p\\u003e\"},{\"_id\":\"cf-xE63h6GjfAhxcaPJ1Kcvm\",\"_type\":\"_\",\"question\":\"Які документи потрібні для перевезення морського контейнера?\",\"answer\":\"\\u003cp\\u003eДля міжнародних перевезень зазвичай потрібні:\\u003c/p\\u003e\\u003cul role=\\u0022list\\u0022\\u003e\\u003cli\\u003eкомерційний інвойс;\\u003c/li\\u003e\\u003cli\\u003eпакувальний лист;\\u003c/li\\u003e\\u003cli\\u003eсертифікати походження або якості (за потреби);\\u003c/li\\u003e\\u003cli\\u003eконосамент (Bill of Lading).\\u2028\\u2028Ми беремо на себе підготовку всіх транспортних документів і перевірку правильності заповнення.\\u2028Клієнт отримує від нас повний пакет для митного оформлення в Україні — без ризику затримок чи штрафів.\\u003c/li\\u003e\\u003c/ul\\u003e\"}]}} /-->', 'ТИПИ ТА РОЗМІРИ МОРСЬКИХ  КОНТЕЙНЕРІВ', '', 'inherit', 'closed', 'closed', '', '724-revision-v1', '', '', '2025-11-10 15:05:29', '2025-11-10 15:05:29', '', 724, 'http://dolphincargo.loc/?p=759', 0, 'revision', '', 0);

